{
  "title": "Maps+ | Milsymbol Demo — Task Force IRON COP (Fulda Gap)",
  "description": "Common Operating Picture: NATO APP-6 / MIL-STD-2525D milsymbol. Hover any symbol for full unit card. Click to pin.",
  "dataSources": {
    "ds_map": {
      "type": "ds.search",
      "name": "Map rows",
      "options": {
        "query": "\n| makeresults\n| eval data=mvappend(\n    \"50.5510|9.6800|sfgpuci----d|A/1-12 IN|TF IRON|INFANTRY|045|18|LEAD ASSAULT - AXIS NORTHEAST|30140800ZOCT24|50.5510N 9.6800E~~<div style='font-family:Arial,sans-serif;width:320px;border-radius:4px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.25);'><div style='background:#1a4f8a;color:white;padding:6px 10px;'><div style='font-size:14px;font-weight:bold;letter-spacing:0.5px;'>A/1-12 IN</div><div style='font-size:10px;opacity:0.75;margin-top:1px;'>FRIENDLY &#183; Company &#183; TF IRON</div></div><div style='background:#006600;color:white;padding:3px 10px;font-size:11px;font-weight:bold;'>CONDUCTING ATTACK</div><div style='background:white;padding:8px 10px;'><table style='border-collapse:collapse;width:100%;'><tr><td style='padding:2px 8px 2px 0;font-size:10px;color:#999;white-space:nowrap;vertical-align:top;text-transform:uppercase;letter-spacing:0.4px;'>Role</td><td style='padding:2px 0;font-size:11px;color:#222;word-wrap:break-word;overflow-wrap:break-word;white-space:normal;max-width:220px;'>Infantry - Lead Assault</td></tr><tr><td style='padding:2px 8px 2px 0;font-size:10px;color:#999;white-space:nowrap;vertical-align:top;text-transform:uppercase;letter-spacing:0.4px;'>Equip</td><td style='padding:2px 0;font-size:11px;color:#222;word-wrap:break-word;overflow-wrap:break-word;white-space:normal;max-width:220px;'>INFANTRY</td></tr><tr><td style='padding:2px 8px 2px 0;font-size:10px;color:#999;white-space:nowrap;vertical-align:top;text-transform:uppercase;letter-spacing:0.4px;'>Mission</td><td style='padding:2px 0;font-size:11px;color:#222;word-wrap:break-word;overflow-wrap:break-word;white-space:normal;max-width:220px;'><span style='line-height:1.5;'>Deliberate attack along Axis NORTHEAST. Seize northern OBJ ANVIL by H+2. C/2-63 AR DS breaching.</span></td></tr><tr><td style='padding:2px 8px 2px 0;font-size:10px;color:#999;white-space:nowrap;vertical-align:top;text-transform:uppercase;letter-spacing:0.4px;'>Dir / Spd</td><td style='padding:2px 0;font-size:11px;color:#222;word-wrap:break-word;overflow-wrap:break-word;white-space:normal;max-width:220px;'><span style='font-family:monospace;'>045&#176; &#160; 18 km/h</span></td></tr><tr><td style='padding:2px 8px 2px 0;font-size:10px;color:#999;white-space:nowrap;vertical-align:top;text-transform:uppercase;letter-spacing:0.4px;'>DTG</td><td style='padding:2px 0;font-size:11px;color:#222;word-wrap:break-word;overflow-wrap:break-word;white-space:normal;max-width:220px;'><span style='font-family:monospace;'>30140800ZOCT24</span></td></tr><tr><td style='padding:2px 8px 2px 0;font-size:10px;color:#999;white-space:nowrap;vertical-align:top;text-transform:uppercase;letter-spacing:0.4px;'>Grid</td><td style='padding:2px 0;font-size:11px;color:#222;word-wrap:break-word;overflow-wrap:break-word;white-space:normal;max-width:220px;'><span style='font-family:monospace;'>50.5510N 9.6800E</span></td></tr><tr><td style='padding:2px 8px 2px 0;font-size:10px;color:#999;white-space:nowrap;vertical-align:top;text-transform:uppercase;letter-spacing:0.4px;'>Notes</td><td style='padding:2px 0;font-size:11px;color:#222;word-wrap:break-word;overflow-wrap:break-word;white-space:normal;max-width:220px;'><span style='color:#555;line-height:1.4;'>CCP at 50.5400N 9.6600E. 2x AVLB engineers attached.</span></td></tr></table></div></div>~~<div style='font-family:Arial,sans-serif;width:320px;border-radius:4px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.25);'><div style='background:#1a4f8a;color:white;padding:6px 10px;'><div style='font-size:14px;font-weight:bold;letter-spacing:0.5px;'>A/1-12 IN</div><div style='font-size:10px;opacity:0.75;margin-top:1px;'>FRIENDLY &#183; Company &#183; TF IRON</div></div><div style='background:#006600;color:white;padding:3px 10px;font-size:11px;font-weight:bold;'>CONDUCTING ATTACK</div><div style='background:white;padding:8px 10px;'><table style='border-collapse:collapse;width:100%;'><tr><td style='padding:2